function defaultHint(){if(state.tab==='learn')return revealedLetter===state.id?t('Listen, then say it with me!','聽一次，再跟著我說！'):t('Tap the card. Listen and meet a letter!','點卡片，聽聲音，認識字母朋友！');if(state.tab==='write')return state.stage==='trace'?t('Watch the line. Then trace the pale letter.','先看線條怎麼走，再描淡色字母。'):state.stage==='copy'?t('Look at the little letter. Can you copy it?','看看小字母，你能照著寫嗎？'):t('Your turn! Try the letter on your own.','換你了！試著自己寫一次。');return quiz?.revealed?t('Look at the picture. Tap its letter friend.','看看圖片，點選它的字母朋友。'):t('Tap the sound to turn the cards over!','點聲音，讓三張卡片翻過來！')}
