 if(phase==='loading'&&!q.revealed)setHint(t('The sound is getting ready. Watch the cards!','聲音準備中，看看卡片！'));
 if(phase==='idle'&&!q.revealed)setHint(defaultHint());
 if(phase!=='playing'||q.revealed)return;
 q.revealed=true;area.classList.add('cards-revealed');$('#quiz-listen').textContent=t('♫ Listen again','♫ 再聽一次');$('#feedback').textContent=t('Which letter is my friend?','哪個字母是我的朋友？');setHint(defaultHint());
 $$('[data-answer]').forEach(b=>{b.setAttribute('aria-label',letters[+b.dataset.answer-1].char);b.querySelector('.answer-front').setAttribute('aria-hidden','false')});
