 on('hint',e=>{if(state.tab==='play'&&!quiz?.revealed){playQuizPrompt();return}TeacherVoice.play(state.tab==='learn'?`explain-${state.id}`:`hint-${state.tab}`,null,e.currentTarget);setHint(defaultHint());$('.coach')?.classList.add('hint-glow');if(state.tab==='play'&&quiz?.tries>0)$(`[data-answer="${state.id}"]`)?.classList.add('hint-answer');if(state.tab==='write'){demoTime=0;demoPlaying=true;paintDemo()}setTimeout(()=>$('.coach')?.classList.remove('hint-glow'),1800)});
